use bhoo::android_time_spinner::{TimeSpinnerField as F,TimeSpinnerState};
#[test] fn minute_wheel_carries_through_noon_and_midnight(){let mut t=TimeSpinnerState::new(11,59,false).unwrap();t.set_field(F::Minute,0).unwrap();assert_eq!((t.hour(),t.minute()),(12,0));assert_eq!(t.range(F::Hour).value,12);assert_eq!(t.range(F::Period).value,1);t.set_field(F::Minute,59).unwrap();assert_eq!((t.hour(),t.minute()),(11,59));let mut t=TimeSpinnerState::new(23,59,true).unwrap();t.set_field(F::Minute,0).unwrap();assert_eq!((t.hour(),t.minute()),(0,0));}
#[test] fn hour_wheel_toggles_period_only_at_eleven_twelve(){let mut t=TimeSpinnerState::new(11,30,false).unwrap();t.set_field(F::Hour,12).unwrap();assert_eq!(t.hour(),12);t.set_field(F::Hour,1).unwrap();assert_eq!(t.hour(),13);t.set_field(F::Period,0).unwrap();assert_eq!(t.hour(),1);t.set_24_hour(true);assert_eq!(t.range(F::Hour).value,1);assert_eq!(t.minute(),30);}
#[test] fn invalid_time_or_field_does_not_mutate(){assert!(TimeSpinnerState::new(24,0,true).is_err());let mut t=TimeSpinnerState::new(8,9,false).unwrap();assert!(t.set_field(F::Minute,60).is_err());assert_eq!((t.hour(),t.minute()),(8,9));}
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_time_picker_spinner.rs"));}
#[test] fn xml_minute_wheel_carries_and_editor_updates_hour(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.time_spinners.insert("time_spinner".into(),TimeSpinnerState::new(11,59,false).unwrap());let b=Rect{x:0.,y:0.,width:360.,height:144.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut a=None;ui.frame(input,b,0.,|f|a=fixture::LAYOUT.render(f,b,s));a};draw(&mut ui,&mut s,Input::default());let point=Some([180.,120.]);draw(&mut ui,&mut s,Input{pointer:point,pressed:true,time:1.,..Input::default()});assert_eq!(draw(&mut ui,&mut s,Input{pointer:point,released:true,time:1.01,..Input::default()}),Some("time_spinner"));assert_eq!((s.time_spinners["time_spinner"].hour(),s.time_spinners["time_spinner"].minute()),(12,0));draw(&mut ui,&mut s,Input{time:1.5,..Input::default()});s.number_picker_editing.insert("time_spinner:H".into());s.text.insert("time_spinner:H".into(),"1".into());assert!(s.end_number_picker_edit("time_spinner:H",true));assert_eq!(draw(&mut ui,&mut s,Input{time:1.6,..Input::default()}),Some("time_spinner"));assert_eq!(s.time_spinners["time_spinner"].hour(),13);}
#[test] fn locale_hour_cycles_preserve_midnight_noon_and_period(){use bhoo::android_time_spinner::HourCycle;let mut t=TimeSpinnerState::new(0,5,false).unwrap();t.set_hour_cycles(HourCycle::H11,HourCycle::H24).unwrap();assert_eq!((t.range(F::Hour).min,t.range(F::Hour).max,t.range(F::Hour).value),(0,11,0));t.set_field(F::Hour,11).unwrap();assert_eq!(t.hour(),23);t.set_field(F::Hour,0).unwrap();assert_eq!(t.hour(),0);t.set_24_hour(true);assert_eq!((t.range(F::Hour).min,t.range(F::Hour).max,t.range(F::Hour).value),(1,24,24));t.set_field(F::Hour,1).unwrap();assert_eq!(t.hour(),1);t.set_field(F::Hour,24).unwrap();assert_eq!(t.hour(),0);assert!(t.set_hour_cycles(HourCycle::H23,HourCycle::H12).is_err());}
